import re

def parse_duration(text):
    # Empty string returns None
    if not text:
        return None

    # If it's a pure number, treat as seconds only
    if text.isdigit():
        return int(text)

    pattern = r'^(h\d+)?(m\d+)?(s\d+)?$'
    match = re.match(pattern, text)

    if not match:
        return None

    total_seconds = 0
    for unit, value in match.groups():
        # Only add seconds if the unit had a valid digit sequence
        if unit == 'h':
            total_seconds += int(value) * 3600 if value else 0
        elif unit == 'm':
            total_seconds += int(value) * 60 if value else 0
        else:  # s
            total_seconds += int(value) if value else 0

    # If we ended up with 0 seconds but the input contained a unit letter,
    # it means there were units without digits (e.g., "h", "m", "s")
    # which is invalid. Return None in that case.
    if total_seconds == 0 and any(c in text.lower() for c in 'hms'):
        return None

    return total_seconds
