def parse_duration(text):
    if not text:
        return None

    # If it's just digits, treat as seconds
    if text.isdigit():
        return int(text)

    hours = 0
    minutes = 0
    seconds = 0
    i = 0
    n = len(text)

    while i < n and text[i].isdigit():
        # Parse number
        j = i
        while j < n and text[j].isdigit():
            j += 1
        num = int(text[i:j])

        # Check what follows the number
        if j < n:
            if text[j] == 'h':
                hours = num
                i = j + 1
            elif text[j] == 'm':
                minutes = num
                i = j + 1
            else:  # must be 's'
                seconds = num
                i = j + 1
        else:
            return None

    # After processing all units, handle remaining 's' for seconds
    if i < n and text[i] == 's':
        j = i
        while j < n and text[j].isdigit():
            j += 1
        seconds = int(text[i:j])
        # If there are digits after this, it's invalid (e.g., "1h30m20x")
        if j < n:
            return None

    # Ensure we've consumed the entire string
    if i != n:
        return None

    total_seconds = hours * 3600 + minutes * 60 + seconds
    return total_seconds
